import logging
import time
import threading
from typing import Optional, Callable

import numpy as np
from faster_whisper import WhisperModel


class WhisperEngine:
    def __init__(self,
                 model_key: str = "tiny",
                 device: str = "cpu",
                 compute_type: str = "int8",
                 language: str = None,
                 beam_size: int = 5,
                 initial_prompt: str = "",
                 hotwords: list = None,
                 vad_manager = None,
                 model_registry = None,
                 dynamic_vocabulary_config = None):

        self.model_key = model_key
        self.device = device
        self.compute_type = compute_type
        self.language = None if language == 'auto' else language
        self.beam_size = beam_size
        self.initial_prompt = initial_prompt or None
        self.hotwords = ", ".join(hotwords) if hotwords else None
        self.model = None
        self.logger = logging.getLogger(__name__)
        self.registry = model_registry
        self.dynamic_vocabulary_config = dynamic_vocabulary_config
        self.dynamic_vocabulary_manager = None

        self._loading_thread = None
        self._progress_callback = None

        self.vad_manager = vad_manager

        self._load_model()
    
    def _get_model_source(self, model_key: str) -> str:
        if self.registry:
            return self.registry.get_source(model_key)
        return model_key

    def _is_model_cached(self, model_key: str = None) -> bool:
        if model_key is None:
            model_key = self.model_key
        if self.registry:
            return self.registry.is_model_cached(model_key)
        return False

    def _load_model(self):
        try:
            print(f"🧠 Loading Whisper AI model [{self.model_key}]...")

            was_cached = self._is_model_cached()
            if not was_cached:
                print("Downloading model, this may take a few minutes....")

            model_source = self._get_model_source(self.model_key)
            self.model = WhisperModel(
                model_source,
                device=self.device,
                compute_type=self.compute_type
            )

            if not was_cached:
                print("\n")  # Workaround for download status bar misplacement

            print(f"   ✓ Whisper model [{self.model_key}] ready!")
            device_label = "GPU" if self.device == "cuda" else "CPU"
            print(f"   ✓ Running on {device_label} with {self.compute_type} precision")

        except Exception as e:
            self.logger.error(f"Failed to load Whisper model: {e}")
            raise
    
    def _load_model_async(self,
                          new_model_key: str,
                          progress_callback: Optional[Callable[[str], None]] = None):
        def notify(message):
            if progress_callback:
                try:
                    progress_callback(message)
                except Exception:
                    self.logger.exception("Model progress callback failed")

        def _background_loader():
            old_model_key = self.model_key
            try:
                notify("Checking model cache...")

                was_cached = self._is_model_cached(new_model_key)

                notify("Loading cached model..." if was_cached else "Downloading model...")

                self.logger.info(f"Loading Whisper model: {new_model_key} (async)")

                model_source = self._get_model_source(new_model_key)
                new_model = WhisperModel(
                    model_source,
                    device=self.device,
                    compute_type=self.compute_type
                )
                self.model = new_model

                self.model_key = new_model_key
                self.logger.info(f"Whisper model [{new_model_key}] loaded successfully (async)")

                notify("Model ready!")

            except Exception as e:
                self.model_key = old_model_key
                self.logger.error(f"Failed to load Whisper model async: {e}")
                notify(f"Failed to load model: {e}")
            finally:
                self._loading_thread = None
                self._progress_callback = None

        if self._loading_thread and self._loading_thread.is_alive():
            self.logger.warning("Model loading already in progress, ignoring new request")
            return
        
        self._progress_callback = progress_callback
        self._loading_thread = threading.Thread(target=_background_loader, daemon=True)
        self._loading_thread.start()
    
    def is_loading(self) -> bool:
        return self._loading_thread is not None and self._loading_thread.is_alive()
    

    def transcribe_audio(self,
                         audio_data: np.ndarray) -> Optional[str]:
        if self.model is None:
            return None
        
        if audio_data is None or len(audio_data) == 0:
            self.logger.warning("No audio data to transcribe")
            return None
        
        try:
            speech_detected = True
            if self.vad_manager and self.vad_manager.is_available():
                speech_detected = self.vad_manager.check_audio_for_speech(audio_data)
            
            if not speech_detected:
                print("   ✗ No speech detected, skipping transcription")
                return None
                       
            start_time = time.perf_counter()  # STT only; excludes recording and delivery.
            
            # Prep audio for faster-whisper
            if len(audio_data.shape) > 1:
                audio_data = audio_data.flatten()
            
            audio_data = audio_data.astype(np.float32)
            
            transcribe_kwargs = dict(
                beam_size=self.beam_size,
                language=self.language,
                condition_on_previous_text=False,
            )
            if self.initial_prompt:
                transcribe_kwargs["initial_prompt"] = self.initial_prompt
            if self.hotwords:
                transcribe_kwargs["hotwords"] = self.hotwords

            # Optional runtime context: failure must not block the existing STT path.
            try:
                dynamic_config = self.dynamic_vocabulary_config
                if isinstance(dynamic_config, dict) and dynamic_config.get('enabled') is True:
                    if self.dynamic_vocabulary_manager is None:
                        from .dynamic_vocabulary import DynamicVocabularyManager
                        self.dynamic_vocabulary_manager = DynamicVocabularyManager(dynamic_config)
                    merged = self.dynamic_vocabulary_manager.hotwords(self.hotwords)
                    if merged:
                        transcribe_kwargs["hotwords"] = merged
            except Exception as exc:
                self.logger.warning("Dynamic vocabulary skipped (%s)", type(exc).__name__)

            segments, info = self.model.transcribe(audio_data, **transcribe_kwargs)
            
            transcribed_text = ""
            for segment in segments:
                transcribed_text += segment.text
            
            transcribed_text = transcribed_text.strip()

            transcription_time = time.perf_counter() - start_time
            print(f"   ✓ STT latency: {transcription_time:.1f} seconds")

            detected_language = info.language
            confidence = info.language_probability
            self.logger.info(f"Transcription complete. Language: {detected_language} (confidence: {confidence:.2f}) - STT latency: {transcription_time:.2f}s")

            if transcribed_text:
                return transcribed_text
            else:
                self.logger.info("Transcription was empty")
                return None
                
        except Exception as e:
            self.logger.error(f"Transcription failed: {e}")
            return None
    
    
    def change_model(self,
                     new_model_key: str,
                     progress_callback: Optional[Callable[[str], None]] = None):
        
        if new_model_key == self.model_key:
            if progress_callback:
                progress_callback("Model already loaded")
            return
        
        self._load_model_async(new_model_key, progress_callback)
